# BIOMOD 2026 - Pandora's Box
# Descriptive statistics supporting Figure 1.
#
# Calculate the percentage of primary acral melanomas:
# 1. Above the 75th percentile of non-sun-exposed skin.
# 2. Above the 75th percentile of sun-exposed skin.
# 3. Below the median of non-sun-exposed skin.
#
# Report exact binomial 95% confidence intervals.
#
# These comparisons are descriptive and exploratory.
# They do not represent protein positivity, therapeutic
# eligibility or a validated target-expression threshold.
#
# Input: private sample metadata generated by script 05.
# Output: aggregate statistics only.

local({

  private_dir <- getOption(
    "biomod.expression.private_dir",
    file.path(tempdir(), "biomod_private")
  )

  input_file <- getOption(
    "biomod.figure1.metadata_file",
    file.path(private_dir, "sample_metadata.csv")
  )

  output_dir <- getOption(
    "biomod.figure1.output_dir", "tables"
  )

  if (!file.exists(input_file)) {
    stop(
      "Missing private sample metadata: ",
      input_file,
      "\nRun script 05 before script 13."
    )
  }

  dir.create(
    output_dir,
    recursive = TRUE,
    showWarnings = FALSE
  )

  # Load individual-level expression data.
  # This input must remain private.

  m <- read.csv(input_file)

  stopifnot(
    all(c("group", "log2TPM1") %in% names(m))
  )

  # Extract the three relevant expression groups.

  g1a <- m$log2TPM1[
    grepl("^G1a", m$group)
  ]

  g1b <- m$log2TPM1[
    grepl("^G1b", m$group)
  ]

  g3 <- m$log2TPM1[
    grepl("^G3", m$group)
  ]

  stopifnot(
    length(g1a) == 604,
    length(g1b) == 701,
    length(g3) == 44,
    all(is.finite(c(g1a, g1b, g3)))
  )

  # Exact binomial confidence intervals.

  summary_row <- function(comparison, k, n) {

    ci <- binom.test(k, n)$conf.int

    data.frame(
      comparison = comparison,
      k = k,
      n = n,
      percentage = 100 * k / n,
      CI95_lower_percent = 100 * ci[1],
      CI95_upper_percent = 100 * ci[2]
    )
  }

  # Preserve the original thresholds and strict
  # greater-than / less-than comparisons.

  results <- rbind(

    summary_row(
      "Acral tumors above the non-sun-exposed skin 75th percentile",
      sum(g3 > quantile(g1a, .75)),
      length(g3)
    ),

    summary_row(
      "Acral tumors above the sun-exposed skin 75th percentile",
      sum(g3 > quantile(g1b, .75)),
      length(g3)
    ),

    summary_row(
      "Acral tumors below the non-sun-exposed skin median",
      sum(g3 < median(g1a)),
      length(g3)
    )
  )

  # Verify the values presented in Figure 1.

  expected <- c(82, 77, 16)

  matches_figure <- all(
    round(results$percentage) == expected
  )

  stopifnot(
    matches_figure,
    all(results$k == c(36, 34, 7)),
    all(results$n == 44)
  )

  print(
    results,
    row.names = FALSE,
    digits = 6
  )

  write.csv(
    results,
    file.path(
      output_dir,
      "figure1_summary_statistics.csv"
    ),
    row.names = FALSE
  )

  cat(
    "\nMatches Figure 1 percentages (82 / 77 / 16):",
    matches_figure,
    "\n"
  )

  # Only aggregate results are exported.

})
